    ('二傅', '이부', '태부(太傅)와 소부(少傅).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二府', '이부', '① 한대(漢代)의 승상(丞相)과 어사(御史)의 일컬음. ② 송(宋)나라 때, 중서성(中書省)·추밀원(樞密院)의 일컬음.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二柄', '이병', '군주(君主)가 신하(臣下)를 제어(制御)하는 두 가지 권병(權柄). 곧, 형벌과 덕(德).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二分', '이분', '① 둘로 나눔. 또, 둘로 나뉨. ② 춘분(春分)과 추분(秋分).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二三', '이삼', '① 두셋. 소수(小數). ② 지조(志操)가 굳지 않아 변절을 잘함.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二三其德', '이삼기덕', '지키지 않고 절개(節槪)를 자주 바꿈.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二三子', '이삼자', '① 스승이 두서넛의 제자를 부르는 말. ② 임금이 두서넛의 대부(大夫)를 부르는 말.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二色', '이색', '두 가지의 빛.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二鼠嚙藤', '이서교등', '[불교] 오욕(五欲)에 집착(執着)하여 벗어나지 못함의 비유. 이서(二鼠)는 달과 해, 등(藤)은 생명을 가리킴.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二姓', '이성', '두 가지의 성(姓).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二聖', '이성', '① 문왕(文王)과 무왕(武王). ② 주공(周公)과 공자(孔子). ③ 대우(大禹)와 공자(孔子).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二姓之合', '이성지합', '성(姓)이 다른 남자와 여자가 혼인(婚姻)하는 일.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二世', '이세', '[불교] 현세(現世)와 내세(來世).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二疏', '이소', '한(漢)나라의 소광(疏廣)·소수(疏受) 두 사람의 일컬음.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二手', '이수', '두 손. 양수(兩手).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二豎', '이수', '병. 질병. 또, 병마(病魔). 진(晉)나라 경공(景公)이 병으로 누워 있을 때 병마(病魔)가 아이 둘로 화신(化身)하여 왔다는 고사(故事)에서 나온 말.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二叔', '이숙', '주(周)나라의 관숙(管叔)과 채숙(蔡叔). 이 두 사람은 주공단(周公旦)의 공(功)을 시새워 유언(流言)을 퍼뜨리고 반란을 일으켰음.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二乘', '이승', '성문승(聲聞乘)과 연각승(緣覺乘). 대승(大乘)과 소승(小乘).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二信', '이신', '신의(信義)를 두 가지로 함. 곧, 이심(二心)을 품음.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二心', '이심', '두 가지 마음. 배반(背叛)하고자 하는 마음.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十', '이십', '스물.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四氣', '이십사기', '15일(日)을 1기(氣)로 하여 1년을 24분(分)한 칭호. 이십사절기.</br></br>| 기(氣) | 양력(陽曆) |</br>| --- | --- |</br>| 입춘(立春) | 2월 4 ~ 5일 |</br>| 우수(雨水) | 2월 19 ~ 20일 |</br>| 경칩(驚蟄) | 3월 5 ~ 6일 |</br>| 춘분(春分) | 3월 21 ~ 22일 |</br>| 청명(淸明) | 4월 5 ~ 6일 |</br>| 곡우(穀雨) | 4월 20 ~ 21일 |</br>| 입하(立夏) | 5월 6 ~ 7일 |</br>| 소만(小滿) | 5월 21 ~ 22일 |</br>| 망종(芒種) | 6월 6 ~ 7일 |</br>| 하지(夏至) | 6월 21 ~ 22일 |</br>| 소서(小暑) | 7월 7 ~ 8일 |</br>| 대서(大暑) | 7월 23 ~ 24일 |</br>| 입추(立秋) | 8월 8 ~ 9일 |</br>| 처서(處暑) | 8월 23 ~ 24일 |</br>| 백로(白露) | 9월 8 ~ 9일 |</br>| 추분(秋分) | 9월 23 ~ 24일 |</br>| 한로(寒露) | 10월 8 ~ 9일 |</br>| 상강(霜降) | 10월 23 ~ 24일 |</br>| 입동(立冬) | 11월 7 ~ 8일 |</br>| 소설(小雪) | 11월 22 ~ 23일 |</br>| 대설(大雪) | 12월 7 ~ 8일 |</br>| 동지(冬至) | 12월 22 ~ 23일 |</br>| 소한(小寒) | 1월 6 ~ 7일 |</br>| 대한(大寒) | 1월 20 ~ 21일 |', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四氣節', '이십사기절', '이십사기(二十四氣).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四番花信風', '이십사번화신풍', '이십사기(二十四氣)의 소한(小寒)에서 곡우(穀雨)까지의 사이의 일후(一候), 곧, 닷새마다 새로운 꽃이 피는 것을 알려 주는 바람.</br></br>![二十四番花信風](img/hanja_24hwasinpung.png)', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四史', '이십사사', '이십이사(二十二史) 중의 당서(唐書)와 오대사(五代史)를 각각 신구(新舊) 두 종류로 나누어 일컫는 말.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四節氣', '이십사절기', '이십사기(二十四氣).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四節候', '이십사절후', '이십사기(二十四氣).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十四孝', '이십사효', '대순(大舜)·한문제(漢文帝)·증삼(曾參)·민손(閔損)·중유(仲由)·동영(董永)·염자(剡子)·강혁(江革)·육적(陸績)·당부인(唐夫人)·오맹(吳猛)·왕상(王祥)·곽거(郭巨)·양향(楊香)·주수창(朱壽昌)·유검루(庾黔婁)·노래자(老萊子)·채순(蔡順)·황향(黃香)·강시(姜詩)·왕포(王裒)·정난(丁蘭)·맹종(孟宗)·황정견(黃庭堅) 등 24인(人)의 효자. 또, 그들의 행적을 적은 책. 원(元)나라 곽거업(郭居業)의 찬(撰).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十世紀', '이십세기', '서력기원 1901년부터 2000년까지의 사이.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十五菩薩', '이십오보살', '부처 다음가는 유덕자(有德者) 25인의 일컬음. 곧, 관세음(觀世音)·대세지(大勢至)·약왕(藥王)·약상(藥上)·보현(普賢)·법자재왕(法自在王)·다라니(陀羅尼)·허공장(虛空藏)·백상왕(白象王)·보장(寶藏)·덕장(德藏)·금장(金藏)·광명왕(光明王)·금강장(金剛藏)·산해혜(山海慧)·화엄왕(華嚴王)·일조왕(日照王)·월광왕(月光王)·중보왕(衆寶王)·삼매왕(三昧王)·사자후(獅子吼)·정자재왕(定自在王)·대위덕왕(大威德王)·대자재왕(大自在王)·무변신왕(無邊身王).', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十五史', '이십오사', '이십사사(二十四史)에 중화민국(中華民國)의 가소민(柯劭忞)이 찬한 〈신원사(新元史)〉를 더한 것.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十五絃', '이십오현', '줄이 스물다섯 있는 큰 거문고.', '2026-11-18T23:00:21.441468Z'::timestamptz),
    ('二十二史', '이십이사', '중국 상대(上代)부터 명(明)나라까지의 22종(種)의 사서(史書).</br></br>| 책명 | 편찬자 |</br>| --- | --- |</br>| 사기(史記) | 사마천(司馬遷) |</br>| 한서(漢書) | 반고(班固) |</br>| 후한서(後漢書) | 범엽(范曄) |</br>| **이상 삼사(三史)** | |</br>| 삼국지(三國志) | 진수(陳壽) |</br>| 진서(晉書) | 방현령(房玄齡) |</br>| 송서(宋書) | 심약(沈約) |</br>| 남제서(南齊書) | 소자현(蕭子顯) |</br>| 양서(梁書) | 요사렴(姚思廉) |</br>| 진서(陳書) | 요사렴(姚思廉) |</br>| 후위서(後魏書) | 위수(魏收) |</br>| 북제서(北齊書) | 이백약(李百藥) |</br>| 주서(周書) | 영호덕분(令狐德棻) |</br>| 수서(隋書) | 위징(魏徵) |</br>| 남사(南史) | 이연수(李延壽) |</br>| 북사(北史) | 이연수(李延壽) |</br>| 당서(唐書) | 구양수(歐陽修) |</br>| 오대사(五代史) | 구양수(歐陽修) |</br>| **이상 십칠사(十七史)** | |</br>| 요사(遼史) | 탁극탁(托克托) |</br>| 금사(金史) | 탁극탁(托克托) |</br>| 송사(宋史) | 탁극탁(托克托) |</br>| 원사(元史) | 송렴(宋濂) |</br>| **이상 이십일사(二十一史)** | |</br>| 명사(明史) | 장정옥(張廷玉) |</br>| **이상 이십이사(二十二史)** | |', '2026-11-18T23:00:21.441468Z'::timestamptz)
),
upd as (
  update public.hanja_dict d
     set meaning = v.meaning,
         updated_at = v.updated_at
    from v
   where d.hanja = v.hanja
     and d.korean = v.korean
  returning d.hanja, d.korean
)
insert into public.hanja_dict (hanja, korean, meaning, created_at, updated_at)
select v.hanja, v.korean, v.meaning, v.updated_at, v.updated_at
  from v
 where not exists (
   select 1 from public.hanja_dict d
    where d.hanja = v.hanja and d.korean = v.korean
 );

commit;
